import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contractPath = path.join(root, "contracts", "workerHub.contract.json");
const contract = JSON.parse(fs.readFileSync(contractPath, "utf8"));

const generatedHeader = [
  "// <auto-generated>",
  "// Generated from contracts/workerHub.contract.json.",
  "// Run: node tools/generate-worker-hub-contracts.mjs",
  "// </auto-generated>",
  "",
].join("\n");

function pascalCase(value) {
  return value
    .replace(/(^|[_-])([a-z])/g, (_, __, letter) => letter.toUpperCase())
    .replace(/^[a-z]/, (letter) => letter.toUpperCase());
}

function tsObject(name, values, valueFormatter) {
  const entries = Object.entries(values)
    .map(([key, value]) => `  ${key}: ${valueFormatter(value)},`)
    .join("\n");
  return `export const ${name} = {\n${entries}\n} as const;\n`;
}

function csClass(name, values, type) {
  const entries = Object.entries(values)
    .map(([key, value]) => {
      const literal = type === "string" ? `\"${value}\"` : value;
      return `            public const ${type} ${pascalCase(key)} = ${literal};`;
    })
    .join("\n");
  return `        public static class ${name}\n        {\n${entries}\n        }\n`;
}

const ts = [
  generatedHeader,
  `export const workerHubPath = ${JSON.stringify(contract.hubPath)} as const;\n`,
  tsObject("workerHubServerMethods", contract.serverMethods, JSON.stringify),
  tsObject("workerHubClientMethods", contract.clientMethods, JSON.stringify),
  tsObject("workerHubRegisterArguments", contract.registerArguments, String),
  tsObject("workerHubCommandOutputChunkArguments", contract.commandOutputChunkArguments, String),
  tsObject("workerHubCommandResultArguments", contract.commandResultArguments, String),
  tsObject("workerHubRefreshCommandTokenArguments", contract.refreshCommandTokenArguments, String),
  tsObject("workerHubRejectCommandArguments", contract.rejectCommandArguments, String),
].join("\n");

const cs = [
  generatedHeader,
  "namespace FirstDraft.Api.Contracts",
  "{",
  "    internal static class WorkerHubContract",
  "    {",
  `        public const string HubPath = \"${contract.hubPath}\";`,
  "",
  csClass("ServerMethods", contract.serverMethods, "string"),
  csClass("ClientMethods", contract.clientMethods, "string"),
  csClass("RegisterArguments", contract.registerArguments, "int"),
  csClass("CommandOutputChunkArguments", contract.commandOutputChunkArguments, "int"),
  csClass("CommandResultArguments", contract.commandResultArguments, "int"),
  csClass("RefreshCommandTokenArguments", contract.refreshCommandTokenArguments, "int"),
  csClass("RejectCommandArguments", contract.rejectCommandArguments, "int"),
  "    }",
  "}",
  "",
].join("\n");

fs.writeFileSync(path.join(root, "api", "src", "contracts", "workerHubContract.ts"), ts);
fs.writeFileSync(path.join(root, "client", "Api", "Contracts", "WorkerHubContract.cs"), cs);
